import {api,send} from './platform.mjs';
import {escapeHtml as esc} from './core.mjs';
import {operationDate,currentTimeZone} from './time.mjs';
import {addDays} from './organizer.mjs';
import {reviewCalendarImport,applyCalendarImport} from './calendar-import.mjs';
const btn=(label,action)=>`<button type="button" class="outline" data-action="gcal-${action}">${label}</button>`;
export function createCalendarConnectUI(ctx){
 const read=ctx.api||api,write=ctx.send||send;let epoch=0,busy=false,pending=null,status=null;
 function cancelPending(){epoch++;busy=false;pending=null;}
 const error=text=>{const el=document.querySelector('#gcal-error');if(el)el.textContent=text;};
 const show=body=>ctx.modal('Google Agenda',body+'<p id="gcal-error" role="alert" tabindex="-1"></p>');
 async function run(work){if(busy)return;busy=true;const at=epoch;try{await work(()=>at===epoch);}catch(e){if(at===epoch)error(e.message);}finally{if(at===epoch)busy=false;}}
 async function open(){cancelPending();show('<p role="status">Conferindo sua conexão…</p>');await run(async valid=>{status=await read('calendar');if(!valid())return;
  const from=operationDate();show(`<p>Traga compromissos da sua agenda principal do Google. Você revisa antes de guardar. A Mentra não envia convites nem altera o Google Agenda.</p>${status.connected?`<p>Calendário conectado.</p><form id="gcal-preview-form" class="form-stack"><label>De<input name="from" type="date" required value="${from}" min="1900-01-01" max="2200-12-31"></label><label>Até<input name="until" type="date" required value="${addDays(from,30)}" min="1900-01-01" max="2200-12-31"></label><p>Até 90 dias e cem ocorrências por consulta. Horários serão apresentados em ${esc(currentTimeZone())}.</p><button class="primary" type="submit">Consultar para revisão</button></form>${btn('Desconectar calendário','disconnect-review')}`:status.configured?`<p>Ao continuar, o Google pedirá sua autorização para leitura. Você escolhe a conta e pode revogar o acesso. Nenhum compromisso entra na Mentra sem sua confirmação.</p>${btn('Continuar para autorizar no Google','connect')}`:'<p>O operador ainda precisa ativar esta conexão. Sua agenda manual continua disponível.</p>'}`);
 });}
 function handleClick(action){if(!action.startsWith('gcal-'))return false;
  if(action==='gcal-open'){void open();return true;}
  if(action==='gcal-connect'){void run(async valid=>{const result=await write('calendar/connect',{confirmed:true});if(!valid())return;const target=new URL(result.url);if(target.origin!=='https://accounts.google.com'||target.pathname!=='/o/oauth2/v2/auth')throw Error('Endereço de autorização inválido.');location.assign(target.href);});return true;}
  if(action==='gcal-disconnect-review'){pending={type:'disconnect'};show(`<p>Desconectar impede novas consultas ao Google. Compromissos já guardados na Mentra permanecem na sua agenda.</p><div class="modal-actions">${btn('Cancelar','back')}${btn('Confirmar desconexão','disconnect')}</div>`);return true;}
  if(action==='gcal-back'){void open();return true;}
  if(action==='gcal-disconnect'&&pending?.type==='disconnect'){void run(async valid=>{const result=await write('calendar',{confirmed:true},'DELETE');if(!valid())return;pending=null;show(`<p>Calendário desconectado da Mentra.</p>${result.revoked?'':'<p>Não foi possível confirmar a revogação no Google. Remova também a permissão da Mentra na sua Conta Google, em conexões com terceiros.</p>'}${btn('Voltar','back')}`);});return true;}
  if(action==='gcal-confirm'&&pending?.type==='import'){const chosen=pending;void run(async valid=>{if(!await ctx.flush())throw Error('Resolva a sincronização antes de importar.');const latest=await read('calendar');if(!valid())return;if(!latest.connected||latest.connectionId!==chosen.review.connectionId)throw Error('A conexão mudou. Consulte novamente.');const state=ctx.getState(),next=applyCalendarImport(state.events,chosen.review);state.events=next;pending=null;ctx.save();ctx.closeModal();ctx.render();ctx.toast('Compromissos preparados para sincronização.');});return true;}
  return true;
 }
 function handleSubmit(form){if(form.id!=='gcal-preview-form')return false;if(!form.checkValidity()){form.reportValidity();return true;}const values=Object.fromEntries(new FormData(form));void run(async valid=>{if(!await ctx.flush())throw Error('Resolva a sincronização antes de consultar.');const proposal=await write('calendar/preview',{...values,timeZone:currentTimeZone()});if(!valid())return;const review=reviewCalendarImport(ctx.getState().events,proposal);pending={type:'import',review};show(`<p><strong>${esc(proposal.calendarName)}</strong> · ${review.changes.length} alterações.</p><p>Cancelamentos ou exclusões no Google não removem compromissos da Mentra. Uma nova consulta pode substituir nome, data, horário e duração das ocorrências importadas, inclusive edições feitas aqui; confira abaixo. Ocorrências canceladas aqui continuam canceladas.</p>${proposal.utcAdjusted?`<p>${proposal.utcAdjusted} horários ambíguos na mudança de fuso serão guardados em UTC para preservar o instante original. Confira o fuso em cada ocorrência.</p>`:''}${proposal.skipped.length?`<p>${proposal.skipped.length} eventos não serão importados (dia inteiro, duração acima de 24h, precisão inferior a um minuto ou formato incompatível): ${proposal.skipped.map(esc).join(', ')}.</p>`:''}<ul class="sync-differences">${review.changes.map(c=>`<li><b>${c.before?'Atualizar':'Adicionar'} · ${esc(c.after.title)}</b><span>${c.before?`${esc(c.before.date)} ${esc(c.before.time)} · ${c.before.duration} min → `:''}${esc(c.after.date)} ${esc(c.after.time)} · ${c.after.duration} min · ${esc(c.after.timeZone)}</span></li>`).join('')||'<li>Nenhuma alteração necessária.</li>'}</ul><div class="modal-actions">${btn('Cancelar','back')}${review.changes.length?btn('Confirmar importação','confirm'):''}</div>`);});return true;}
 return {open,handleClick,handleSubmit,cancelPending};
}
